[data-ryt="pitch"] { color: rgb(55, 60, 68); border-left: 3px solid rgb(15, 76, 129); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.3; letter-spacing: -0.192px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(55, 60, 68); text-decoration-thickness: auto; text-underline-offset: 1.6px; padding-top: 16px; padding-right: 16px; padding-bottom: 16px; padding-left: 24px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 8px; box-shadow: rgba(129, 145, 181, 0.016) 0.232px 0.464px 2.784px 0px, rgba(129, 145, 181, 0.024) 0.536px 1.072px 6.432px 0px, rgba(129, 145, 181, 0.03) 1px 2px 12px 0px, rgba(129, 145, 181, 0.035) 1.8px 3.6px 21.6px 0px, rgba(129, 145, 181, 0.043) 3.336px 6.672px 40.032px 0px, rgba(129, 145, 181, 0.06) 8px 16px 96px 0px, rgba(129, 145, 181, 0.016) 0px 0px 0px 1px; transition: border-color 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), box-shadow 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), transform 0.22s cubic-bezier(0.22, 0.61, 0.24, 1) }
[data-ryt="footer"] { color: var(--ryt-text); background-color: rgb(244, 242, 237); border-top: 1px solid var(--ryt-border); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-accent) 50%, transparent); text-decoration-thickness: auto; text-underline-offset: 2.375px; transition: background-color 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), color 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), text-decoration 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), box-shadow 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), -webkit-text-decoration 0.22s cubic-bezier(0.22, 0.61, 0.24, 1) }
[data-ryt="hero"] h1 { color: rgb(55, 60, 68); font-family: var(--ryt-font-body); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(55, 60, 68); text-decoration-thickness: auto; text-underline-offset: 1.6px; transition: all }
[data-ryt="section"] > h2 { color: rgb(45, 49, 56); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; line-height: 1.1; letter-spacing: -0.812px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(45, 49, 56); text-decoration-thickness: auto; text-underline-offset: 1.6px; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: rgb(15, 76, 129); background-color: rgb(232, 236, 238); border-top: 1px solid rgb(168, 183, 192); border-right: 1px solid rgb(168, 183, 192); border-bottom: 1px solid rgb(168, 183, 192); border-left: 1px solid rgb(168, 183, 192); border-radius: 999px; font-family: var(--ryt-font-body); font-weight: 500; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(15, 76, 129); text-decoration-thickness: auto; text-underline-offset: 1.6px; padding-top: 4px; padding-right: 9.6px; padding-bottom: 4px; padding-left: 9.6px; transition: all }
[data-ryt="review"] { color: var(--ryt-muted); font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.78; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: 1.6px; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: ui-monospace, SFMono-Regular, "SF Mono", "Cascadia Mono", Menlo, Consolas, "Liberation Mono", monospace; font-size: 14px; font-weight: 500; font-style: normal; line-height: 1.45; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: 1.6px; transition: all }
[data-ryt="cover"] { border-radius: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a { color: rgb(55, 60, 68); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; letter-spacing: -0.266px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(55, 60, 68); text-decoration-thickness: auto; text-underline-offset: 2.375px; transition: background-color 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), color 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), text-decoration 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), box-shadow 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), -webkit-text-decoration 0.22s cubic-bezier(0.22, 0.61, 0.24, 1); position: relative }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 19px; font-weight: 600; font-style: normal; line-height: 1.65; letter-spacing: -0.266px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 2.375px; transition: all }
[data-ryt="header"] { border-bottom: 1px solid rgba(0, 0, 0, 0); border-top: none }
[data-ryt="nav"] a { color: rgb(86, 93, 102); border-radius: 4px; font-family: var(--ryt-font-body); font-size: 15px; font-weight: 500; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(86, 93, 102); text-decoration-thickness: auto; text-underline-offset: 1.875px; padding-top: 7.2px; padding-right: 11.2px; padding-bottom: 7.2px; padding-left: 11.2px; transition: background-color 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), color 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), text-decoration 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), box-shadow 0.22s cubic-bezier(0.22, 0.61, 0.24, 1), -webkit-text-decoration 0.22s cubic-bezier(0.22, 0.61, 0.24, 1) }
[data-ryt="button"] { color: var(--ryt-surface); background-color: rgb(15, 76, 129); border-top: 1px solid rgb(15, 76, 129); border-right: 1px solid rgb(15, 76, 129); border-bottom: 1px solid rgb(15, 76, 129); border-left: 1px solid rgb(15, 76, 129); border-radius: 4px; font-family: var(--ryt-font-body); font-weight: 500; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-surface); text-decoration-thickness: auto; text-underline-offset: 1.75px; padding-top: 8px; padding-right: 12.8px; padding-bottom: 8px; padding-left: 12.8px; transition: background-color 0.12s cubic-bezier(0.22, 0.61, 0.24, 1), border-color 0.12s cubic-bezier(0.22, 0.61, 0.24, 1), color 0.12s cubic-bezier(0.22, 0.61, 0.24, 1), transform 0.12s cubic-bezier(0.22, 0.61, 0.24, 1), box-shadow 0.12s cubic-bezier(0.22, 0.61, 0.24, 1) }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(55, 60, 68); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 19px; font-weight: 500; font-style: normal; line-height: 1.3; letter-spacing: -0.266px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(55, 60, 68); text-decoration-thickness: auto; text-underline-offset: 1.6px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { opacity: 1 }
body:hover { opacity: 1 }
[data-ryt="button"]:hover { opacity: 1; background-color: color-mix(in srgb, #0f4c81 86%, #000); color: #ffffff; transform: translateY(-1px); box-shadow: 0 1px 2px rgb(16 20 23 / 4%), 0 1px 3px rgb(16 20 23 / 4%) }
[data-ryt="nav"] a:hover { opacity: 1; color: #15181c; background-color: #f4f2ed }
[data-ryt="header"]:hover { opacity: 1 }
[data-ryt="brand"]:hover { opacity: 1 }
[data-ryt="rec-card"] [data-ryt="title"] a::after { content: ""; display: block; position: absolute; width: 100%; height: 577.906px; color: rgb(55, 60, 68); background-size: auto; background-position: 0% 0%; background-repeat: no-repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 19px; font-weight: 500; font-style: normal; line-height: 1.3; letter-spacing: -0.266px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(55, 60, 68); text-decoration-thickness: auto; text-underline-offset: 2.375px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(55, 60, 68); top: 0px; left: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { opacity: 1 }
[data-ryt="cover"]:hover { opacity: 1 }
[data-ryt="credit"]:hover, [data-ryt="eyebrow"]:hover { opacity: 1 }
[data-ryt="review"]:hover { opacity: 1 }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { opacity: 1 }
[data-ryt="section"] > h2:hover { opacity: 1 }
[data-ryt="hero"] h1:hover { opacity: 1 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { opacity: 1 }
[data-ryt="footer"]:hover { opacity: 1 }
article[data-ryt="rec-card"]:hover { opacity: 1; box-shadow: 0 2px 4px rgb(16 20 23 / 4%), 0 8px 24px rgb(16 20 23 / 6%) }
[data-ryt="pitch"]:hover { opacity: 1 }
